mapper.select:
SELECT s.stu_id, s.student_no, s.user_id, u.real_name, u.phone, u.password
FROM my_student s, my_sys_user u
WHERE s.user_id = u.user_id AND s.student_no = #{studentNo}

mapper.update:
UPDATE my_sys_user u, my_student s
SET
    u.real_name = #{name},
    u.phone = #{phone},
    u.email = #{email}
WHERE s.user_id = u.user_id AND s.stu_id = #{stuId}

mapper.select:
SELECT u.password
FROM my_sys_user u, my_student s
WHERE s.user_id = u.user_id AND s.stu_id = #{stuId}

mapper.update:
UPDATE my_sys_user u, my_student s
SET u.password = #{newPassword}
WHERE s.user_id = u.user_id AND s.stu_id = #{stuId}
